{
  "title": "Tumor B Cell Shield",
  "perWatchSecond": 1,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "The B Cell Shield",
      "goal": "See how a large tBreg population drives tumor growth despite active NK cell killing.",
      "control": {
        "parameter": "c",
        "label": "NK killing rate",
        "lowEnd": "1e-10",
        "highEnd": "1e-8"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Start with 500,000,000 tBregs instead of 500,000.",
        "parameter": "b0",
        "value": 500000000
      },
      "difference": {
        "compartment": "t",
        "summary": "at",
        "at": 70,
        "time": 70,
        "relation": "higher",
        "by": 100
      },
      "effect": "With 500 million tBregs at the start instead of 500,000, the tumor is over 100 cells larger at day 70, even with the same NK killing rate.",
      "prediction": {
        "prompt": "The second world starts with 500,000,000 tBregs instead of 500,000. At day 70, which world has more cancer cells?",
        "claimed": "The tBreg world has more cancer cells",
        "other": "The normal world has more cancer cells"
      },
      "passage": {
        "title": "Headline result",
        "quote": "a sufficiently large number of tBregs can cause the breast tumour to reach its carrying capacity, regardless of the rate of NK-induced breast cancer cell death."
      },
      "carryForward": "Large tBreg populations drive tumor growth even with active NK cells. Next, we see what happens when tBregs persist instead of dying off."
    },
    {
      "kind": "result",
      "finding": 2,
      "title": "NK Cells as Gatekeepers",
      "goal": "See how persistent tBregs suppress NK cells and allow a larger tumor to grow.",
      "control": {
        "parameter": "c",
        "label": "NK killing rate",
        "lowEnd": "1e-10",
        "highEnd": "1e-8"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Set the tBreg death rate to zero so tBregs never disappear.",
        "parameter": "thetaB",
        "value": 0
      },
      "difference": {
        "compartment": "t",
        "summary": "at",
        "at": 70,
        "time": 70,
        "relation": "higher",
        "by": 50
      },
      "effect": "When tBregs never die, they keep boosting Tregs and suppressing NK cells, so the tumor is over 50 cells larger at day 70.",
      "prediction": {
        "prompt": "The second world has no tBreg death. At day 70, which world has more cancer cells?",
        "claimed": "The no-death world has more cancer cells",
        "other": "The normal world has more cancer cells"
      },
      "passage": {
        "title": "NK control without tBregs",
        "quote": "when tBregs do not exist in the body, the only way for the breast tumour to reach its carrying capacity is for the rate of NK-induced breast cancer cell death to be tending to 0"
      },
      "carryForward": "Without tBreg persistence, NK cells keep the tumor in check. Next, we explore how the tBreg death rate controls whether tBregs vanish or remain."
    },
    {
      "kind": "idea",
      "finding": 5,
      "title": "The Treg Tug-of-War",
      "goal": "See how the tBreg death rate determines whether tBregs persist or vanish over time.",
      "control": {
        "parameter": "thetaB",
        "label": "tBreg death rate",
        "lowEnd": "0.01",
        "highEnd": "1.0"
      },
      "watch": "b",
      "whatIf": {
        "prompt": "Cut the tBreg death rate to 0.04, one tenth of the default.",
        "parameter": "thetaB",
        "value": 0.04
      },
      "difference": {
        "compartment": "b",
        "summary": "at",
        "at": 15,
        "time": 15,
        "relation": "higher",
        "by": 10000
      },
      "effect": "With the tBreg death rate cut from 0.4 to 0.04, tBregs are over 10,000 more numerous at day 15.",
      "prediction": {
        "prompt": "The second world has a tBreg death rate of 0.04 instead of 0.4. At day 15, which world has more tBregs?",
        "claimed": "The low-death world has more tBregs",
        "other": "The normal world has more tBregs"
      },
      "passage": {
        "title": "tBreg decline condition",
        "quote": "when θB/mT > 1/b, our model has no closed orbits, meaning that breast cancer will either be cleared by NK cells or stabilise around a constant number."
      },
      "carryForward": "tBregs decline rapidly when their death rate is high. Next, we find the critical NK killing rate that eliminates the tumor entirely."
    },
    {
      "kind": "result",
      "finding": 4,
      "title": "The Killing Threshold",
      "goal": "Find the NK killing rate above which the tumor is eliminated rather than persisting.",
      "control": {
        "parameter": "c",
        "label": "NK killing rate",
        "lowEnd": "1e-10",
        "highEnd": "5e-10"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Raise the NK killing rate to 5e-10, well above the default.",
        "parameter": "c",
        "value": 5e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "at",
        "at": 70,
        "time": 70,
        "relation": "lower",
        "by": 20
      },
      "effect": "When NK killing is raised from 2e-10 to 5e-10, the tumor is eliminated and is over 20 cells lower at day 70.",
      "prediction": {
        "prompt": "The second world has NK killing rate 5e-10 instead of 2e-10. At day 70, which world has more cancer cells?",
        "claimed": "The normal world has more cancer cells",
        "other": "The high-killing world has more cancer cells"
      },
      "passage": {
        "title": "Transcritical bifurcation",
        "quote": "System [reducedModel] experiences a transcritical bifurcation at the equilibrium point E1 ≡ E2 as the parameter c varies through c1."
      },
      "carryForward": "Above a critical NK killing rate the tumor is eliminated. The interplay of tBregs, Tregs, and NK cells determines whether a breast tumor persists or is cleared."
    }
  ],
  "limits": [
    "The model uses absolute cell counts, not fractions; a value of 5 means 5 cancer cells.",
    "tBregs decay exponentially with rate thetaB; the tumor-induced growth term mT*t is negligible at these cell counts.",
    "The carrying capacity of the tumor is 1/b2 = 1,000,000,000 cells, far beyond the 70-day window.",
    "NK cells and Tregs are in the hundreds of millions; small percentage changes in their death rates shift tumor growth noticeably.",
    "The transcritical bifurcation in c occurs near 3e-10, where NK killing balances tumor growth."
  ]
}
